def bres(p,q):
    (r0,c0),(r1,c1)=p,q
    cells=[]; dr,dc=abs(r1-r0),abs(c1-c0)
    sr=1 if r1>r0 else -1; sc=1 if c1>c0 else -1
    err=dr-dc; r,c=r0,c0
    while True:
        cells.append((r,c))
        if (r,c)==(r1,c1): break
        e2=2*err
        if e2>-dc: err-=dc; r+=sr
        if e2<dr: err+=dr; c+=sc
    return cells
